from collections import deque

data = sys.stdin.read().split()
n = int(data[0])
a = tuple(int(x) for x in data[1:1 + n])
target = tuple(sorted(a))
if n <= 7:
    dist = {a: 0}
    dq = deque([a])
    while dq:
        cur = dq.popleft()
        if cur == target:
            break
        for i in range(n):
            for j in range(i + 1, n):
                nxt = list(cur)
                nxt[i], nxt[j] = nxt[j], nxt[i]
                nxt = tuple(nxt)
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    dq.append(nxt)
    print(dist[target])
else:
    arr = list(a)
    swaps = 0
    for i in range(n):
        while arr[i] != i + 1:
            j = arr[i] - 1
            arr[i], arr[j] = arr[j], arr[i]
            swaps += 1
    print(swaps)

